[DataContractAttribute]
public class RMarketMethod_Bybit_QueryApi
    extends RMarketMethod
    implements RMarketMethodInterface_GetApiKeyInfo
{
    private RMarketJson_Bybit_QueryApi_Result result;

    [DataMemberAttribute('result')]
    public RMarketJson_Bybit_QueryApi_Result parmResult(
        RMarketJson_Bybit_QueryApi_Result _result = result)
    {
        result = _result;
        return result;
    }

    public str getExchangeUid()
    {
        return int642Str(responseContract.parmResult().parmUserID());
    }

    public str getParentUid()
    {
        return responseContract.parmResult().parmParentUid();
    }

    public boolean isMaster()
    {
        return responseContract.parmResult().parmIsMaster();
    }

    public boolean isReadOnly()
    {
        return responseContract.parmResult().parmReadOnly() == 1;
    }

    public utcdatetime getExpirationDateTime()
    {
        str value = responseContract.parmResult().parmExpiredAt();

        return value
        ? RMarketJsonSerializer::deserializeDateTime(value)
        : DateTimeUtil::minValue();
    }
}
